Aquí está una función en C++ que toma una referencia a un `std::string` que contiene texto con formato Markdown y devuelve un `std::string` que contiene texto con formato HTML:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <regex>

std::string markdown_to_html(const std::string& markdown) {
    // Define Markdown syntax patterns
    std::regex italic_regex("\\*(.+?)\\*");
    std::regex bold_regex("\\**(.*?)\\**");
    std::regex header_regex("\\#(\\s+)?(.+?)\\s*(\\n|$)");
    std::regex link_regex("\\[(.+?)\\]\\((.*?)\\)");
    std::regex code_block_regex("```(.*?)\\n((.|\n)*?)\\n```");

    std::stringstream ss;
    bool in_code_block = false;

    // Loop through each line of Markdown
    for (const auto& line : std::string_view(markdown).split('\n')) {
        std::string formatted_line;

        // Italic
        std::smatch match;
        if (std::regex_search(line, match, italic_regex)) {
            formatted_line += "<em>" + match[1] + "</em>";
        } else {
            formatted_line += line;
        }

        // Bold
        std::regex_search(formatted_line, match, bold_regex);
        if (match.size() > 0) {
            formatted_line = "<strong>" + match[1] + "</strong>" + formatted_line.substr(match.position() + match.length());
        }

        // Header
        std::regex_search(formatted_line, match, header_regex);
        if (match.size() > 0) {
            std::string level = std::string(match[1].length(), '#');
            formatted_line = "<h" + level + ">" + match[2] + "</h" + level + ">";
            formatted_line = formatted_line.substr(match.position(), match.length());
        }

        // Link
        std::regex_search(formatted_line, match, link_regex);
        if (match.size() > 0) {
            std::string link_text = match[1];
            std::string link_url = match[2];
            formatted_line = "<a href=\"" + link_url + "\">" + link_text + "</a>";
            formatted_line = formatted_line.substr(match.position(), match.length());
        }

        // Code block
        std::regex_search(formatted_line, match, code_block_regex);
        if (match.size() > 0) {
            std::string language = match[1];
            std::string code = match[2];
            std::string pre_tag = "<pre><code class=\"" + language + "\">";
            std::string post_tag = "</code></pre>";
            if (in_code_block) {
                pre_tag = "";
                post_tag = "</code></pre>";
            }
            formatted_line = pre_tag + code + post_tag;
            formatted_line = formatted_line.substr(match.position(), match.length());
            in_code_block = !in_code_block;
        }

        ss << formatted_line << '\n';
    }

    std::string html = ss.str();
    html.erase(html.size() - 1); // Remove trailing newline

    return html;
}

int main() {
    std::string markdown = "Hello **world**! # This is a header\n\n[Google](https://www.google.com/)";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Este ejemplo implementa los siguientes patrones de Markdown:

- Itálico: `\*(.+?)\*`
- Negritud: `\**(.*?)\**`
- Encabezados: `#\s*(.+)`
- Enlaces: `\[(.+?)\]\((.*?)\)`
- Bloques de código: ```(.*?)\n((.|\n)*?)\n```

El código utiliza un bucle para iterar sobre cada línea de Markdown y aplicar los patrones correspondientes para convertir cada línea en HTML. Los resultados son concatenados en una cadena `stringstream` para devolver el texto completo en formato HTML. Se debe recordar que este código no es una solución completa y puede tener errores o carencias. Se recomienda usar una biblioteca de conversión de Markdown a HTML como, por ejemplo, [Pandoc](https://pandoc.org/) o [CommonMark](https://spec.commonmark.org/) para una solución más robusta.

